mapper.select:
select mn.*, dep.D_Name as mrReportDepartmentName, cd.Construction_Drawing_Code as mrReportConstructionDrawingCode ,c1.C_Name as mrCName ,u1.U_Name as mrRepairUname, u2.U_Name as mrDispatchUname,u3.U_Name as mrCreateUname, cd.construction_Drawing_Name as mrConstructionDrawingName from Maintenance_Record mn left join sys_department dep on mn.Mr_Report_Department_Id = dep.D_Id left join SYS_Company c1 on c1.C_Id=mn.Mr_C_Id left join sys_user u1 on u1.U_ID=mn.Mr_Repair_Uid left join sys_user u2 on u2.U_ID=mn.Mr_Dispatch_Uid left join sys_user u3 on u3.U_ID=mn.Mr_Create_Uid left join construction_drawing cd on cd.id=mn.Mr_Report_Construction_Drawing_Id ${params.authSql}
and mn.p_name like concat('%',#{params.pName},'%')
and mn.mr_serial_number like concat('%',#{params.mrSerialNumber},'%')
and dep.D_Name like concat('%',#{params.mrReportDepartmentName},'%')
and mn.mr_state=#{params.mrState}
and mn.Mr_Create_Time between #{params.createTimeRange[0]} and #{params.createTimeRange[1]}
and mn.Mr_Id not in (select distinct ccc.mr_id from construction_completion_confirm ccc where ccc.state!=3)
and mn.Mr_Id not in (select distinct rc.mr_id from Renovatio_Changes rc where rc.state!=3)
and mn.Mr_Id not in (select distinct rv.mr_id from Renovatio_Visa rv where rv.state!=3)
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Mr_Create_Time desc

select mn.*, dep.D_Name as mrReportDepartmentName, cd.Construction_Drawing_Code as mrConstructionDrawingCode ,c1.C_Name as mrCName ,u1.U_Name as mrRepairUname,u2.U_Name as mrDispatchUname,u3.U_Name as mrCreateUname, cd.construction_Drawing_Name as mrConstructionDrawingName from Maintenance_Record mn left join sys_department dep on mn.Mr_Report_Department_Id = dep.D_Id left join SYS_Company c1 on c1.C_Id=mn.Mr_C_Id left join sys_user u1 on u1.U_ID=mn.Mr_Repair_Uid left join sys_user u2 on u2.U_ID=mn.Mr_Dispatch_Uid left join sys_user u3 on u3.U_ID=mn.Mr_Create_Uid left join construction_drawing cd on cd.id=mn.Mr_Report_Construction_Drawing_Id
mn.Mr_State not in (0,3,2,9)
and mn.p_name like concat('%',#{params.pName},'%')
and mn.mr_serial_number like concat('%',#{params.mrSerialNumber},'%')
and YEAR(mn.Mr_Report_Time) = #{params.year}
and MONTH(mn.Mr_Report_Time) = #{params.month}
and mn.mr_repair_state in
#{item}
and mn.mr_report_time between #{params.startTime} and #{params.endTime}

select state
from Application_Warranty
where Mr_Id = #{mrId}

select dtl.mr_id, case max(case when settlement.state = 7 then 3 when settlement.state not in (0, 3, 7) then 2 when settlement.state = 3 then 1 else 0 end) when 3 then '4' when 2 then '8' when 1 then '3' end as mr_repair_state from sporadic_settlement_dtl dtl join sporadic_settlement settlement on settlement.id = dtl.se_id where dtl.mr_id in
#{mrId}
and settlement.state != 0 group by dtl.mr_id

select ssd.mr_id, case max(case when payments.state = 7 then 3 when payments.state not in (0, 3, 7) then 2 when payments.state = 3 then 1 else 0 end) when 3 then '6' when 2 then '9' when 1 then '4' end as mr_repair_state from sporadic_payments payments join sporadic_payments_dtl spd on spd.sp_p_did = payments.id join sporadic_settlement settlement on settlement.id = spd.sp_d_id join sporadic_settlement_dtl ssd on ssd.se_id = settlement.id where settlement.state = 7 and payments.state != 0 and ssd.mr_id in
#{mrId}
group by ssd.mr_id
